object NewBalanceChapter2Part4 {
    val quests = listOf(
        Quest("CH2-130",2,130,"Tengron's Ring",category="Valley of Mines",giver = "Tengron",location="Valley of Mines",prerequisites="Start Miners and Ore and reach Fajeth's mining camp in the Valley of Mines.",summary="Carry the paladin Tengron's ring from Fajeth's mining camp to Udar in the castle.",walkthroughSteps=listOf("Find Tengron, the paladin stationed at the entrance to Fajeth's mining camp.","Accept his request to deliver a ring to fellow paladin Udar.","Travel to Garond's castle and find Udar on guard duty.","Hand over Tengron's ring to Udar to complete the errand."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Complete the related faction and chapter prerequisites before this objective. Source: https://rpgrussia.com/threads/kolco-tengrona.67091/",searchTags=listOf("tengron's ring","valley of mines","local quest giver in valley of mines")),
        Quest("CH2-131",2,131,"Reinforcements for Marcos",category="Valley of Mines",giver="Marcos",location="Valley of Mines",prerequisites="Chapter 2; complete earlier quests in the same area/faction if the dialogue is not yet available.",summary="Ask Garond to send reinforcements to Marcos.",walkthroughSteps=listOf("Find Marcos at his Valley of Mines position.","Ask how you can help; he requests additional troops.","Go to Garond in the castle and ask for support for Marcos.","Return to Marcos when the support request has been dealt with."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Do not sell unique named items, special ingredients, quest letters or unusual trophies until the related quest chain is finished.",searchTags=listOf("reinforcements for marcos","valley of mines","local quest giver in valley of mines","marcos")),
        Quest("CH2-132",2,132,"Hunting Glorks",category="Valley of Mines",giver="Fajeth",location="Valley of Mines",prerequisites="Start Miners and Ore by Garond, then speak with Fajeth at his ore miners' camp.",summary="Kill eight specific snappers (glorks) threatening Fajeth's mining camp, then report to him.",walkthroughSteps=listOf("Travel to Fajeth's mining camp in the Valley of Mines while following Garond's Miners and Ore assignment.","Speak to Fajeth; he asks you to kill the snappers (glorks) surrounding his camp.","Kill three snappers beside the lake; one spawns only after Fajeth gives the quest. Nearby dragon snappers do not count.","Kill two more along the road toward Xardas's old tower; again, dragon snappers accompanying them are not part of the count.","Climb the ledge above the mining camp and kill three more snappers; two appear only once the hunt has started.","Report the eight kills to Fajeth to complete his quest.","Before leaving, speak to Bilgot about the pack leader to unlock the associated special snapper and his optional escape quest. The leader is guarded by three dragon snappers but does not count toward the required eight."),reward="1,000 XP for Fajeth's snapper hunt; an optional 800 XP for the special pack leader, according to the April 2026 New Balance guide.",warnings="This is a separate quest from Kervo's Snappers (CH2-124). The eight required creatures are: 3 by the lake, 2 by the road to Xardas's tower, 3 on the ledge above camp. Dragon snappers, the leader and its escorts do not count. Source: https://rpgrussia.com/threads/oxota-na-glorxov.67088/",searchTags=listOf("hunting glorks","valley of mines","local quest giver in valley of mines")),
        Quest("CH2-133",2,133,"Bilgot's Escape",category="Valley of Mines",giver = "Bilgot",location="Valley of Mines",prerequisites="Start Fajeth's Hunting Snappers quest and speak to Bilgot about the creatures.",summary="Escort Bilgot safely from Fajeth's mining camp to the pass out of the Valley of Mines.",walkthroughSteps=listOf("At Fajeth's mining camp, accept the snapper hunt and question Bilgot about the pack's leader.","Bilgot provides information but asks you to help him escape the valley.","Before beginning the escort, clear dangerous monsters along the route from the mine toward the pass.","Ask Bilgot to follow you; Diego can also be escorted along part of the route when his guide quest is active.","Lead Bilgot all the way to the mountain pass and speak to him to finish the escort."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Bilgot has limited survivability and can die in combat; clear the route first. The quest can be taken even after returning Fajeth's hunting quest. Source: https://rpgrussia.com/threads/pobeg-bilgota.67090/",searchTags=listOf("bilgot's escape","valley of mines","local quest giver in valley of mines")),
