        Quest("CH2-136",2,136,"Raven's Ring",category="Valley of Mines",giver="Drax",location="Valley of Mines",prerequisites="Chapter 2; complete earlier quests in the same area/faction if the dialogue is not yet available.",summary="Bring Raven's ring to Drax at the forest camp behind the palisade.",walkthroughSteps=listOf("Speak to Drax at the camp beyond the orc palisade.","Fight Raven in the Temple of Adanos and obtain his ring.","Return to Drax and deliver the ring."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Unique equipment can be tied to several quests. Do not sell, forge away or discard it before checking all related dialogue.",searchTags=listOf("raven's ring","valley of mines","local quest giver in valley of mines","drax")),
