        Quest("CH2-140",2,140,"Ur-Shak",category="Valley of Mines",giver = "Ur-Shak",location="Valley of Mines",prerequisites="Chapter 2; complete earlier quests in the same area/faction if the dialogue is not yet available.",summary="Help friendly orc shaman Ur-Shak regain his standing by asking Ur-Thrall to speak for him.",walkthroughSteps=listOf("Find Ur-Shak on the hill near Xardas's old tower and ask about his position among the orcs.","Ur-Shak asks you to speak favorably of him to orc chieftain Ur-Thrall if an opportunity arises.","Complete Ur-Thrall's Revenge and defeat Azgalor in the Valley of Shadows.","Keep Ur-Grom alive and in corporeal form; tell Ur-Thrall that his brother Ur-Grom survived.","When Ur-Thrall offers to grant a request in thanks, ask him to help Ur-Shak.","Return to Ur-Shak to tell him the good news and close the quest."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Killing Hosh-Pak can cause Ur-Shak to become hostile; a Forgetfulness spell may reset his hostility in some builds. Source: https://rpgrussia.com/threads/ur-shak.67295/",searchTags=listOf("ur-shak","valley of mines","local quest giver in valley of mines")),
        Quest("CH2-141",2,141,"Orc Drakkar",category="Valley of Mines",giver="Albert",location="Valley of Mines",prerequisites="Complete Albert's initial request for orders from Garond.",summary="Sabotage the orc warship's mechanism at Albert's request.",walkthroughSteps=listOf("Speak to Albert at the small paladin camp below Netbek's forest camp.","Reach the orc drakkar nearby and enter its hold.","Set the ship's internal mechanism on fire using a torch.","Escape and report the sabotage to Albert."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Ulu-Mulu will not protect you aboard the ship. Orc armor or an invisibility potion may help.",searchTags=listOf("orc drakkar","valley of mines","local quest giver in valley of mines","albert")),
        Quest("CH2-142",2,142,"Orc War Plans",category="Valley of Mines",giver="Albert",location="Valley of Mines",prerequisites="Progress Albert's orc drakkar quest and clear the orcs on the ship.",summary="Recover and decipher the orc war plans, then stop their construction project.",walkthroughSteps=listOf("Kill the orcs on the drakkar, including their leader, and take the letter from the chief.","Show the orc-language note to Albert.","Ask Ur-Shak to translate it, or learn to read the orc language from the note in Xardas's old tower.","The plans reveal a new battering ram aimed at the castle.","Find the orcs near the breach in the palisade, defeat them and return to Albert."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Albert offers two paladins as support, but you need not take them along.",searchTags=listOf("orc war plans","valley of mines","local quest giver in valley of mines","albert")),
