        Quest("CH2-145",2,145,"Freeing Gorn",category="Valley of Mines - Castle",giver = "Milten",location="Valley of Mines - Castle",prerequisites="Complete before Chapter 3 for the direct rescue route.",summary="Raise Gorn's 1,000-gold ransom, pay Garond and release him from the castle prison.",walkthroughSteps=listOf("Ask Milten in Garond's castle about your old companions and learn that Gorn is imprisoned.","Speak to Garond, who demands 1,000 gold for Gorn's release.","Return to Milten and Diego, who can contribute 250 and 300 gold respectively.","Optionally take another 350 gold from Gorn's stash inside the ruined tower section near the castle's ram.","Pay Garond the full ransom and visit Gorn in the prison.","Free Gorn and meet him and Milten in the mages' quarters to finish the rescue."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="If you do not release Gorn in Chapter 2, Milten frees him later and Gorn appears at Onar's farm. Source: https://rpgrussia.com/threads/osvobozhdenie-gorna.66945/",searchTags=listOf("freeing gorn","valley of mines - castle","local quest giver in valley of mines - castle")),
        Quest("CH2-146",2,146,"Escape",category="Valley of Mines - Castle",giver="Cliff",location="Valley of Mines - Castle",prerequisites="Free Gorn from the castle prison and wait several days.",summary="Help Cliff escape the castle and reach Netbek's forest camp.",walkthroughSteps=listOf("Speak to Cliff about his plan to escape.","Locate Netbek's forest camp and return to Cliff with a destination.","At night, bring Cliff a weapon and either hunters' armor or minecrawler-plate armor.","Meet Cliff near the castle's ram and escort him to Netbek's camp near the shapeshifters' monastery.","Use the key awarded at the camp on the chest in the former Rice Lord's house; it leads to another chest key in the castle tower."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Save before starting long escorts. If the NPC stops, clear nearby enemies, move back toward them, and trigger any pending dialogue before continuing. ",searchTags=listOf("escape","valley of mines - castle","local quest giver in valley of mines - castle","cliff")),
        Quest("CH2-147",2,147,"Oric's Pleas",category="Valley of Mines - Castle",giver = "Oric",location="Valley of Mines - Castle",prerequisites="Chapter 2; complete earlier quests in the same area/faction if the dialogue is not yet available.",summary="Bring paladin Oric a small statuette of Innos to restore his spirits in Garond's castle.",walkthroughSteps=listOf("Speak with paladin Oric inside Garond's castle about the missing shrine to Innos.","Look for a small Innos statuette in your inventory or buy one elsewhere.","If you have none, search the locked chest in the right-hand room on the castle's second floor.","Give Oric the statuette to complete his request."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Complete the related faction and chapter prerequisites before this objective. Source: https://rpgrussia.com/threads/molby-orika.66947/",searchTags=listOf("oric's pleas","valley of mines - castle","local quest giver in valley of mines - castle")),
